// lib/strategies/smart-grid-strategy.ts

export type MarketRegime = "BULLISH" | "NEUTRAL" | "BEARISH";

export type VolatilityStatus = "NORMAL" | "FAST" | "EXTREME";

export type StrategyAction = "BUY" | "SELL" | "HOLD" | "WAIT";

export interface StrategyConfig {
  // Grid settings
  buyDropPercent: number;
  sellProfitPercent: number;

  // Market score
  bullishScore: number;
  bearishScore: number;

  // Movement speed
  normalMovementMinutes: number;
  fastMovementMinutes: number;

  // Risk / position limits
  maxPositions: number;
  positionSize: number;

  // How close the current price must be to the grid level
  priceTolerancePercent: number;
}

export interface GridPosition {
  id: string;
  buyPrice: number;
  quantity: number;
  openedAt: number;
}

export interface PricePoint {
  price: number;
  timestamp: number;
}

export interface StrategyInput {
  currentPrice: number;
  marketScore: number;

  /**
   * Price history is used to determine how quickly
   * the market moved by the configured percentage.
   */
  priceHistory: PricePoint[];

  /**
   * Available quote currency, e.g. USDT/USD.
   */
  availableCapital: number;

  /**
   * Existing open positions.
   * The last item is considered the newest position.
   */
  positions: GridPosition[];
}

export interface StrategyDecision {
  action: StrategyAction;

  reason: string;

  marketRegime: MarketRegime;

  volatilityStatus: VolatilityStatus;

  currentPrice: number;

  nextBuyPrice: number | null;

  nextSellPrice: number | null;

  targetPositionId: string | null;

  targetPositionBuyPrice: number | null;

  positionProfitPercent: number | null;

  movementPercent: number | null;

  movementDurationMinutes: number | null;
}

/**
 * Default configuration.
 *
 * All important strategy values are configurable.
 */
export const DEFAULT_SMART_GRID_CONFIG: StrategyConfig = {
  buyDropPercent: 3,
  sellProfitPercent: 3,

  bullishScore: 70,
  bearishScore: 30,

  normalMovementMinutes: 20,
  fastMovementMinutes: 10,

  maxPositions: 10,
  positionSize: 100,

  priceTolerancePercent: 0.05,
};

/**
 * Generate a simple unique position ID.
 */
function generatePositionId(): string {
  return `grid-${Date.now()}-${Math.random()
    .toString(36)
    .substring(2, 9)}`;
}

/**
 * Convert a score into a market regime.
 */
export function getMarketRegime(
  score: number,
  config: StrategyConfig = DEFAULT_SMART_GRID_CONFIG
): MarketRegime {
  if (score >= config.bullishScore) {
    return "BULLISH";
  }

  if (score < config.bearishScore) {
    return "BEARISH";
  }

  return "NEUTRAL";
}

/**
 * Calculate the next BUY level.
 *
 * If there are no positions, the caller should provide
 * the initial reference price separately.
 */
export function calculateNextBuyPrice(
  lastBuyPrice: number,
  config: StrategyConfig = DEFAULT_SMART_GRID_CONFIG
): number {
  return lastBuyPrice * (1 - config.buyDropPercent / 100);
}

/**
 * Calculate the SELL target for a position.
 */
export function calculateSellPrice(
  buyPrice: number,
  config: StrategyConfig = DEFAULT_SMART_GRID_CONFIG
): number {
  return buyPrice * (1 + config.sellProfitPercent / 100);
}

/**
 * Calculate current profit percentage for a position.
 */
export function calculateProfitPercent(
  buyPrice: number,
  currentPrice: number
): number {
  if (buyPrice <= 0) {
    return 0;
  }

  return ((currentPrice - buyPrice) / buyPrice) * 100;
}

/**
 * Check whether the current price has reached a target.
 */
export function isPriceAtOrAbove(
  currentPrice: number,
  targetPrice: number,
  tolerancePercent: number
): boolean {
  const tolerance = targetPrice * (tolerancePercent / 100);

  return currentPrice >= targetPrice - tolerance;
}

/**
 * Check whether the current price has reached a BUY level.
 *
 * BUY levels are downward levels, therefore the current price
 * must be at or below the target.
 */
export function isPriceAtOrBelow(
  currentPrice: number,
  targetPrice: number,
  tolerancePercent: number
): boolean {
  const tolerance = targetPrice * (tolerancePercent / 100);

  return currentPrice <= targetPrice + tolerance;
}

/**
 * Find how long it took the market to move by the configured
 * percentage.
 *
 * This searches backward through the price history and finds
 * a historical price that represents the required movement.
 *
 * Example:
 *
 * Current price = $94
 * Movement threshold = 3%
 *
 * The function searches for the most recent earlier price
 * around $97.
 */
export function calculateMovementDuration(
  currentPrice: number,
  priceHistory: PricePoint[],
  movementPercent: number
): {
  movementPercent: number | null;
  durationMinutes: number | null;
} {
  if (
    currentPrice <= 0 ||
    priceHistory.length === 0 ||
    movementPercent <= 0
  ) {
    return {
      movementPercent: null,
      durationMinutes: null,
    };
  }

  const threshold = movementPercent / 100;

  const lowerReference = currentPrice / (1 - threshold);
  const upperReference = currentPrice / (1 + threshold);

  let bestPoint: PricePoint | null = null;

  /*
   * We look for either:
   *
   * 1. A previous price approximately 3% ABOVE current price
   *    → downward 3% movement.
   *
   * 2. A previous price approximately 3% BELOW current price
   *    → upward 3% movement.
   *
   * The closest valid historical point is used.
   */

  let bestDistance = Infinity;

  for (const point of priceHistory) {
    if (point.timestamp >= Date.now()) {
      continue;
    }

    if (point.price <= 0) {
      continue;
    }

    const distanceDown = Math.abs(point.price - lowerReference);
    const distanceUp = Math.abs(point.price - upperReference);

    const distance = Math.min(distanceDown, distanceUp);

    if (distance < bestDistance) {
      bestDistance = distance;
      bestPoint = point;
    }
  }

  if (!bestPoint) {
    return {
      movementPercent: null,
      durationMinutes: null,
    };
  }

  const actualMovement =
    ((currentPrice - bestPoint.price) / bestPoint.price) * 100;

  const durationMinutes =
    (Date.now() - bestPoint.timestamp) / (1000 * 60);

  return {
    movementPercent: Math.abs(actualMovement),
    durationMinutes,
  };
}

/**
 * Determine movement speed.
 */
export function getVolatilityStatus(
  durationMinutes: number | null,
  config: StrategyConfig = DEFAULT_SMART_GRID_CONFIG
): VolatilityStatus {
  if (durationMinutes === null) {
    return "NORMAL";
  }

  if (durationMinutes < config.fastMovementMinutes) {
    return "EXTREME";
  }

  if (durationMinutes < config.normalMovementMinutes) {
    return "FAST";
  }

  return "NORMAL";
}

/**
 * Get the newest position.
 *
 * This is the LIFO position.
 */
export function getNewestPosition(
  positions: GridPosition[]
): GridPosition | null {
  if (positions.length === 0) {
    return null;
  }

  return positions[positions.length - 1];
}

/**
 * Determine whether the newest position is profitable enough
 * to sell.
 */
export function isProfitableEnoughToSell(
  position: GridPosition,
  currentPrice: number,
  config: StrategyConfig
): boolean {
  const profitPercent = calculateProfitPercent(
    position.buyPrice,
    currentPrice
  );

  return profitPercent >= config.sellProfitPercent;
}

/**
 * Main strategy engine.
 *
 * IMPORTANT:
 *
 * This function does not execute any exchange order.
 *
 * It only decides:
 *
 * BUY
 * SELL
 * HOLD
 * WAIT
 *
 * Your trading/execution layer should execute the returned action.
 */
export function evaluateSmartGridStrategy(
  input: StrategyInput,
  config: StrategyConfig = DEFAULT_SMART_GRID_CONFIG,
  initialReferencePrice?: number
): StrategyDecision {
  const {
    currentPrice,
    marketScore,
    priceHistory,
    availableCapital,
    positions,
  } = input;

  const marketRegime = getMarketRegime(
    marketScore,
    config
  );

  const movement = calculateMovementDuration(
    currentPrice,
    priceHistory,
    config.buyDropPercent
  );

  const volatilityStatus = getVolatilityStatus(
    movement.durationMinutes,
    config
  );

  /*
   * ---------------------------------------------------------
   * BASIC VALIDATION
   * ---------------------------------------------------------
   */

  if (currentPrice <= 0) {
    return {
      action: "WAIT",
      reason: "Invalid current price.",
      marketRegime,
      volatilityStatus,
      currentPrice,
      nextBuyPrice: null,
      nextSellPrice: null,
      targetPositionId: null,
      targetPositionBuyPrice: null,
      positionProfitPercent: null,
      movementPercent: movement.movementPercent,
      movementDurationMinutes: movement.durationMinutes,
    };
  }

  /*
   * ---------------------------------------------------------
   * POSITION INFORMATION
   * ---------------------------------------------------------
   */

  const newestPosition = getNewestPosition(positions);

  let nextBuyPrice: number | null = null;

  if (newestPosition) {
    nextBuyPrice = calculateNextBuyPrice(
      newestPosition.buyPrice,
      config
    );
  } else if (initialReferencePrice) {
    /*
     * If there are no positions yet, use the initial
     * strategy reference price.
     */
    nextBuyPrice = calculateNextBuyPrice(
      initialReferencePrice,
      config
    );
  }

  /*
   * ---------------------------------------------------------
   * SELL INFORMATION
   * ---------------------------------------------------------
   */

  let nextSellPrice: number | null = null;

  let positionProfitPercent: number | null = null;

  if (newestPosition) {
    nextSellPrice = calculateSellPrice(
      newestPosition.buyPrice,
      config
    );

    positionProfitPercent = calculateProfitPercent(
      newestPosition.buyPrice,
      currentPrice
    );
  }

  /*
   * ---------------------------------------------------------
   * SELL LOGIC
   * ---------------------------------------------------------
   *
   * SELL is checked before BUY because an existing
   * profitable position should be handled first.
   *
   * LIFO means newestPosition is always the position
   * considered for selling.
   */

  if (newestPosition && nextSellPrice !== null) {
    const sellTargetReached = isPriceAtOrAbove(
      currentPrice,
      nextSellPrice,
      config.priceTolerancePercent
    );

    if (sellTargetReached) {
      /*
       * EXTREME MOVEMENT
       *
       * We do not immediately sell during an extreme
       * price movement.
       */
      if (volatilityStatus === "EXTREME") {
        return {
          action: "WAIT",
          reason:
            "Sell target reached, but price movement is extremely fast. Waiting for the market to stabilize.",
          marketRegime,
          volatilityStatus,
          currentPrice,
          nextBuyPrice,
          nextSellPrice,
          targetPositionId: newestPosition.id,
          targetPositionBuyPrice: newestPosition.buyPrice,
          positionProfitPercent,
          movementPercent: movement.movementPercent,
          movementDurationMinutes:
            movement.durationMinutes,
        };
      }

      /*
       * STRONGLY BEARISH
       *
       * If the market is strongly bearish and the position
       * is already profitable by at least 3%, sell it.
       */
      if (
        marketRegime === "BEARISH" &&
        isProfitableEnoughToSell(
          newestPosition,
          currentPrice,
          config
        )
      ) {
        return {
          action: "SELL",
          reason:
            "Sell target reached and market score is bearish. Close the newest profitable position.",
          marketRegime,
          volatilityStatus,
          currentPrice,
          nextBuyPrice,
          nextSellPrice,
          targetPositionId: newestPosition.id,
          targetPositionBuyPrice: newestPosition.buyPrice,
          positionProfitPercent,
          movementPercent: movement.movementPercent,
          movementDurationMinutes:
            movement.durationMinutes,
        };
      }

      /*
       * BULLISH
       *
       * Do not automatically sell a profitable position
       * when the market is strongly bullish.
       */
      if (marketRegime === "BULLISH") {
        return {
          action: "HOLD",
          reason:
            "Sell target reached, but the market is strongly bullish. Hold the newest position.",
          marketRegime,
          volatilityStatus,
          currentPrice,
          nextBuyPrice,
          nextSellPrice,
          targetPositionId: newestPosition.id,
          targetPositionBuyPrice: newestPosition.buyPrice,
          positionProfitPercent,
          movementPercent: movement.movementPercent,
          movementDurationMinutes:
            movement.durationMinutes,
        };
      }

      /*
       * NEUTRAL
       *
       * In a neutral market, a normal +3% target is enough
       * to sell.
       */
      if (marketRegime === "NEUTRAL") {
        return {
          action: "SELL",
          reason:
            "Sell target reached in a neutral market. Close the newest position using LIFO.",
          marketRegime,
          volatilityStatus,
          currentPrice,
          nextBuyPrice,
          nextSellPrice,
          targetPositionId: newestPosition.id,
          targetPositionBuyPrice: newestPosition.buyPrice,
          positionProfitPercent,
          movementPercent: movement.movementPercent,
          movementDurationMinutes:
            movement.durationMinutes,
        };
      }
    }
  }

  /*
   * ---------------------------------------------------------
   * BUY LOGIC
   * ---------------------------------------------------------
   */

  if (nextBuyPrice !== null) {
    const buyLevelReached = isPriceAtOrBelow(
      currentPrice,
      nextBuyPrice,
      config.priceTolerancePercent
    );

    if (buyLevelReached) {
      /*
       * EXTREME MOVEMENT
       *
       * Never open a new grid position while the market
       * has moved 3% extremely quickly.
       */
      if (volatilityStatus === "EXTREME") {
        return {
          action: "WAIT",
          reason:
            "Buy level reached, but the 3% movement happened too quickly. Wait for the market to stabilize.",
          marketRegime,
          volatilityStatus,
          currentPrice,
          nextBuyPrice,
          nextSellPrice,
          targetPositionId: null,
          targetPositionBuyPrice: null,
          positionProfitPercent,
          movementPercent: movement.movementPercent,
          movementDurationMinutes:
            movement.durationMinutes,
        };
      }

      /*
       * CAPITAL CHECK
       */
      if (availableCapital < config.positionSize) {
        return {
          action: "WAIT",
          reason:
            "Buy level reached, but there is not enough available capital.",
          marketRegime,
          volatilityStatus,
          currentPrice,
          nextBuyPrice,
          nextSellPrice,
          targetPositionId: null,
          targetPositionBuyPrice: null,
          positionProfitPercent,
          movementPercent: movement.movementPercent,
          movementDurationMinutes:
            movement.durationMinutes,
        };
      }

      /*
       * MAX POSITION CHECK
       */
      if (positions.length >= config.maxPositions) {
        return {
          action: "WAIT",
          reason:
            "Buy level reached, but the maximum number of positions has been reached.",
          marketRegime,
          volatilityStatus,
          currentPrice,
          nextBuyPrice,
          nextSellPrice,
          targetPositionId: null,
          targetPositionBuyPrice: null,
          positionProfitPercent,
          movementPercent: movement.movementPercent,
          movementDurationMinutes:
            movement.durationMinutes,
        };
      }

      /*
       * BULLISH
       *
       * Normal buy condition.
       */
      if (marketRegime === "BULLISH") {
        return {
          action: "BUY",
          reason:
            "Buy level reached in a bullish market with acceptable movement speed.",
          marketRegime,
          volatilityStatus,
          currentPrice,
          nextBuyPrice,
          nextSellPrice,
          targetPositionId: null,
          targetPositionBuyPrice: null,
          positionProfitPercent,
          movementPercent: movement.movementPercent,
          movementDurationMinutes:
            movement.durationMinutes,
        };
      }

      /*
       * NEUTRAL
       *
       * Normal grid buying is allowed.
       */
      if (marketRegime === "NEUTRAL") {
        return {
          action: "BUY",
          reason:
            "Buy level reached in a neutral market with acceptable movement speed.",
          marketRegime,
          volatilityStatus,
          currentPrice,
          nextBuyPrice,
          nextSellPrice,
          targetPositionId: null,
          targetPositionBuyPrice: null,
          positionProfitPercent,
          movementPercent: movement.movementPercent,
          movementDurationMinutes:
            movement.durationMinutes,
        };
      }

      /*
       * BEARISH
       *
       * Be more conservative.
       *
       * The first version allows buying only when the movement
       * is NORMAL, not FAST.
       */
      if (marketRegime === "BEARISH") {
        if (volatilityStatus === "FAST") {
          return {
            action: "WAIT",
            reason:
              "Buy level reached in a bearish market, but the price is falling too quickly. Wait.",
            marketRegime,
            volatilityStatus,
            currentPrice,
            nextBuyPrice,
            nextSellPrice,
            targetPositionId: null,
            targetPositionBuyPrice: null,
            positionProfitPercent,
            movementPercent: movement.movementPercent,
            movementDurationMinutes:
              movement.durationMinutes,
          };
        }

        return {
          action: "BUY",
          reason:
            "Buy level reached in a bearish market, but movement speed is normal. Allow a conservative grid purchase.",
          marketRegime,
          volatilityStatus,
          currentPrice,
          nextBuyPrice,
          nextSellPrice,
          targetPositionId: null,
          targetPositionBuyPrice: null,
          positionProfitPercent,
          movementPercent: movement.movementPercent,
          movementDurationMinutes:
            movement.durationMinutes,
        };
      }
    }
  }

  /*
   * ---------------------------------------------------------
   * NOTHING TO DO
   * ---------------------------------------------------------
   */

  return {
    action: "HOLD",
    reason:
      "No buy or sell condition has been reached. Continue monitoring.",
    marketRegime,
    volatilityStatus,
    currentPrice,
    nextBuyPrice,
    nextSellPrice,
    targetPositionId: newestPosition?.id ?? null,
    targetPositionBuyPrice: newestPosition?.buyPrice ?? null,
    positionProfitPercent,
    movementPercent: movement.movementPercent,
    movementDurationMinutes: movement.durationMinutes,
  };
}

/**
 * Create a new position after a BUY decision.
 *
 * This does NOT place an exchange order.
 * It only creates the local strategy position object.
 */
export function createGridPosition(
  buyPrice: number,
  positionSize: number
): GridPosition {
  const quantity = positionSize / buyPrice;

  return {
    id: generatePositionId(),
    buyPrice,
    quantity,
    openedAt: Date.now(),
  };
}

/**
 * Remove the newest position after a SELL.
 *
 * This implements LIFO.
 */
export function removeNewestPosition(
  positions: GridPosition[]
): GridPosition | null {
  if (positions.length === 0) {
    return null;
  }

  return positions[positions.length - 1];
}
